import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import FilterPanel from "./FilterPanel.js";

describe("FilterPanel", () => {
  it("stacks the count, the chips, Search and the facets, in order", () => {
    render(
      <FilterPanel
        chips="zone 1"
        count="3 lines"
        facets="Zone"
        search={<input aria-label="Search" />}
      />,
    );
    const panel = screen.getByRole("complementary", { name: "Filters" });
    expect(panel.dataset.region).toBe("filter-panel");
    expect(
      [...panel.children].map((slot) => (slot as HTMLElement).dataset.slot),
    ).toEqual(["count", "chips", "search", "facets"]);
  });

  it("leaves out a slot it is not given", () => {
    render(<FilterPanel count="3 lines" />);
    expect(
      [...screen.getByRole("complementary").children].map(
        (slot) => (slot as HTMLElement).dataset.slot,
      ),
    ).toEqual(["count"]);
  });

  it("applies custom className and passes native props through", () => {
    render(<FilterPanel className="custom-class" data-testid="panel" />);
    const panel = screen.getByTestId("panel");
    expect(panel.className).toContain("ds filter-panel");
    expect(panel.className).toContain("custom-class");
  });
});
